create table if not exists api_keys(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,key_hash text not null,scopes jsonb not null default '[]',last_used_at timestamptz,created_at timestamptz default now(),revoked_at timestamptz);
create table if not exists webhooks(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),url text not null,events jsonb not null default '[]',secret_hash text,active boolean default true,created_at timestamptz default now());
create table if not exists integration_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),provider text not null,event_type text not null,payload jsonb not null,attempts int default 0,status text default 'pending',last_error text,created_at timestamptz default now());
